INSERT INTO page_content VALUES(1,'home','hero_heading','Compassionate Care for Every Animal','ప్రతి జంతువుకు కరుణతో కూడిన సేవ','हर जानवर के लिए करुणामय देखभाल','ஒவ்வொரு விலங்குக்கும் இரக்கமான பராமரிப்பு','2026-05-31 06:04:51.704 +00:00');
INSERT INTO page_content VALUES(2,'home','hero_subheading','Free veterinary services for rural and tribal communities','గ్రామీణ మరియు గిరిజన సముదాయాలకు ఉచిత పశు వైద్య సేవలు','ग्रामीण और आदिवासी समुदायों के लिए निःशुल्क पशु चिकित्सा सेवाएं','கிராமப்புற மற்றும் பழங்குடி சமூகங்களுக்கு இலவச கால்நடை சேவைகள்','2026-05-31 06:04:51.718 +00:00');
INSERT INTO page_content VALUES(3,'home','mission_text','To provide compassionate, professional, and free veterinary care to animals belonging to underprivileged communities, regardless of the owner''s ability to pay.','సేవ చెల్లించే సామర్థ్యతో సంబంధం లేకుండా అట్టడుగు వర్గాలకు చెందిన జంతువులకు కరుణతో, వృత్తిపరంగా మరియు ఉచితంగా పశు వైద్య సేవలు అందించడం.','मालिक की भुगतान क्षमता की परवाह किए बिना वंचित समुदायों के जानवरों को दयालु, पेशेवर और निःशुल्क पशु चिकित्सा देखभाल प्रदान करना।','உரிமையாளரின் செலுத்தும் திறன் பொருட்படுத்தாமல், பின்தங்கிய சமூகங்களைச் சேர்ந்த விலங்குகளுக்கு இரக்கமான, தொழில்முறை மற்றும் இலவச கால்நடை பராமரிப்பை வழங்குதல்.','2026-05-31 06:04:51.726 +00:00');
INSERT INTO page_content VALUES(4,'home','vision_text','A world where every animal, regardless of its owner''s economic background, has access to modern, compassionate veterinary care.','యజమాని యొక్క ఆర్థిక నేపథ్యంతో సంబంధం లేకుండా ప్రతి జంతువు ఆధునిక, కరుణతో కూడిన పశు వైద్య సేవలను పొందగలిగే ప్రపంచం.','एक ऐसी दुनिया जहां हर जानवर, चाहे उसके मालिक की आर्थिक पृष्ठभूमि कुछ भी हो, आधुनिक और करुणामय पशु चिकित्सा देखभाल तक पहुंच सके।','உரிமையாளரின் பொருளாதார பின்னணி பொருட்படுத்தாமல், ஒவ்வொரு விலங்கும் நவீன, இரக்கமான கால்நடை பராமரிப்பை அணுகக்கூடிய உலகம்.','2026-05-31 06:04:51.731 +00:00');
INSERT INTO page_content VALUES(5,'about','story_paragraph_1','MAA Saraswati Veterinary Hospital was inaugurated in July 2024 with a mission to provide free, high-quality veterinary care to animals in rural and tribal communities across Telangana and beyond.','','','','2026-05-31 06:04:51.736 +00:00');
INSERT INTO page_content VALUES(6,'about','story_paragraph_2','Our facility is equipped with a modern operation theatre, fully-functional laboratory, ICU/observation wards, and a 24/7 ambulance service that covers the twin cities and up to 100 km from Hyderabad.','','','','2026-05-31 06:04:51.742 +00:00');
INSERT INTO page_content VALUES(7,'contact','address','MAA Saraswati Veterinary Hospital, Hyderabad, Telangana, India','MAA సరస్వతి పశు వైద్యశాల, హైదరాబాద్, తెలంగాణ, భారతదేశం','MAA सरस्वती पशु चिकित्सालय, हैदराबाद, तेलंगाना, भारत','MAA சரஸ்வதி கால்நடை மருத்துவமனை, ஹைதராபாத், தெலங்கானா, இந்தியா','2026-05-31 06:04:51.747 +00:00');
